package studio.solocamera;
public final class TakeNamingTest {public static void main(String[] args){String a=TakeNaming.filename("JJ Complex / Wedding","Scene: 02",3,1234);if(!a.equals("JJ-Complex-Wedding_Scene-02_T003_1234.mp4"))throw new AssertionError(a);String b=TakeNaming.filename("../../","",-1,4);if(!b.equals("take_T001_4.mp4")||b.contains("/"))throw new AssertionError(b);if(TakeNaming.safe("x".repeat(100)).length()!=32)throw new AssertionError();if(!TakeNaming.filename("Événement","Speeches",7,5).endsWith("_T007_5.mp4"))throw new AssertionError();System.out.println("PASS event/scene/take names, traversal rejection, length limits and Unicode names");}}
